<script>document.querySelectorAll('.contributor-toggle').forEach(x=>x.onchange=async()=>{if(!confirm('Change this contributor status?')){x.checked=!x.checked;return}let r=await fetch(x.dataset.url,{method:'PATCH',headers:{'X-CSRF-TOKEN':'{{csrf_token()}}','Accept':'application/json'}});if(!r.ok){alert('Unable to change status');x.checked=!x.checked}else location.reload()});document.querySelectorAll('.edit-btn').forEach(btn=>{btn.onclick=()=>{document.getElementById('editForm').action=btn.dataset.action;document.getElementById('editName').value=btn.dataset.name||'';document.getElementById('editEmail').value=btn.dataset.email||'';document.getElementById('editPhone').value=btn.dataset.phone||'';document.getElementById('editDescription').value=btn.dataset.description||''}})</script>
